/* ==========================================================================
   jQuery plugin settings and other scripts
   ========================================================================== */

$(function() {
  // Floating TOC toggle logic
  var $tocBtn = $('#toc-toggle-btn');
  var $tocFloat = $('#toc-float');
  var $tocClose = $('#toc-close-btn');
  var tocActiveClass = 'toc-float--active';
  var tocHiddenClass = 'toc-float--hidden';
  function openTOC() {
    console.log('[TOC] openTOC called');
    // Find the main TOC list generated by toc.html (class toc__menu)
    var $tocMenu = $('.toc__menu').first();
    var $panelList = $tocFloat.find('.toc-float__list');
    var $emptyMsg = $tocFloat.find('.toc-float__empty');
    if ($tocMenu.length > 0 && $tocMenu.html().trim() !== '') {
      // Only inject the inner HTML of the TOC (li's), not the outer <ul>
      $panelList.html($tocMenu.children().clone());
      $panelList.show();
      $emptyMsg.hide();
    } else {
      $panelList.hide();
      $emptyMsg.show();
    }
    $tocFloat.removeClass(tocActiveClass).removeClass(tocHiddenClass).addClass(tocActiveClass);
    $('body').addClass('toc-float-open');
    $tocFloat.attr('aria-hidden', 'false');
    $tocBtn.attr('aria-expanded', 'true');
    setTimeout(function() {
      $tocFloat.focus();
    }, 400);
    console.log('[TOC] Panel opened');
  }
  function closeTOC() {
    console.log('[TOC] closeTOC called');
    $tocFloat.removeClass(tocActiveClass).removeClass(tocHiddenClass).addClass(tocHiddenClass);
    $('body').removeClass('toc-float-open');
    $tocFloat.attr('aria-hidden', 'true');
    $tocBtn.attr('aria-expanded', 'false');
    $tocBtn.focus();
    console.log('[TOC] Panel closed');
  }
  $tocBtn.on('click', function(e) {
    e.preventDefault();
    console.log('[TOC] toc-toggle-btn clicked');
    if ($tocFloat.hasClass(tocActiveClass)) {
      closeTOC();
    } else {
      openTOC();
    }
  });

  // --- 패널 바깥에서 휠 내리면 자동 닫힘 ---
  var tocMouseInside = false;
  $tocFloat.on('mouseenter', function() {
    tocMouseInside = true;
  });
  $tocFloat.on('mouseleave', function() {
    tocMouseInside = false;
  });
  $(document).on('wheel', function(e) {
    if ($tocFloat.hasClass(tocActiveClass) && !tocMouseInside) {
      closeTOC();
    }
  });
  $tocClose.on('click', function(e) {
    console.log('[TOC] toc-close-btn clicked');
    e.stopPropagation();
    closeTOC();
  });
  // Close when clicking outside the TOC area (modal only)
  $tocFloat.on('mousedown', function(e) {
    console.log('[TOC] toc-float mousedown', e.target === this);
    if (e.target === this) closeTOC();
  });
  // ESC key closes TOC
  $(document).on('keyup', function(e) {
    if ($tocFloat.hasClass(tocActiveClass) && (e.key === 'Escape' || e.keyCode === 27)) {
      console.log('[TOC] ESC pressed, closing');
      closeTOC();
    }
  });
  // Prevent scroll on background when TOC open
  $tocFloat.on('wheel touchmove', function(e) {
    if ($tocFloat.hasClass(tocActiveClass)) {
      console.log('[TOC] Prevent scroll event');
      e.stopPropagation();
    }
  });


  // Sticky sidebar
  var stickySideBar = function() {
    var show =
      $(".author__urls-wrapper").find("button").length === 0
        ? $(window).width() > 1024 // width should match $large Sass variable
        : !$(".author__urls-wrapper").find("button").is(":visible");
    if (show) {
      // fix
      $(".sidebar").addClass("sticky");
    } else {
      // unfix
      $(".sidebar").removeClass("sticky");
    }
  };

  stickySideBar();

  $(window).resize(function() {
    stickySideBar();
  });

  // Follow menu drop down
  $(".author__urls-wrapper").find("button").on("click", function() {
    $(".author__urls").toggleClass("is--visible");
    $(".author__urls-wrapper").find("button").toggleClass("open");
  });

  // Close search screen with Esc key
  $(document).keyup(function(e) {
    if (e.keyCode === 27) {
      if ($(".initial-content").hasClass("is--hidden")) {
        $(".search-content").toggleClass("is--visible");
        $(".initial-content").toggleClass("is--hidden");
      }
    }
  });

  // Search toggle
  $(".search__toggle").on("click", function() {
    $(".search-content").toggleClass("is--visible");
    $(".initial-content").toggleClass("is--hidden");
    // set focus on input
    setTimeout(function() {
      $(".search-content").find("input").focus();
    }, 400);
  });


  // Gumshoe scroll spy init
  if($("nav.toc").length > 0) {
    var spy = new Gumshoe("nav.toc a", {
      // Active classes
      navClass: "active", // applied to the nav list item
      contentClass: "active", // applied to the content

      // Nested navigation
      nested: false, // if true, add classes to parents of active link
      nestedClass: "active", // applied to the parent items

      // Offset & reflow
      offset: 20, // how far from the top of the page to activate a content area
      reflow: true, // if true, listen for reflows

      // Event support
      events: true // if true, emit custom events
    });
  }

  // add lightbox class to all image links
  $(
    "a[href$='.jpg'],a[href$='.jpeg'],a[href$='.JPG'],a[href$='.png'],a[href$='.gif'],a[href$='.webp']"
  ).has("> img").addClass("image-popup");

  // Magnific-Popup options
  $(".image-popup").magnificPopup({
    // disableOn: function() {
    //   if( $(window).width() < 500 ) {
    //     return false;
    //   }
    //   return true;
    // },
    type: "image",
    tLoading: "Loading image #%curr%...",
    gallery: {
      enabled: true,
      navigateByImgClick: true,
      preload: [0, 1] // Will preload 0 - before current, and 1 after the current image
    },
    image: {
      tError: '<a href="%url%">Image #%curr%</a> could not be loaded.'
    },
    removalDelay: 500, // Delay in milliseconds before popup is removed
    // Class that is added to body when popup is open.
    // make it unique to apply your CSS animations just to this exact popup
    mainClass: "mfp-zoom-in",
    callbacks: {
      beforeOpen: function() {
        // just a hack that adds mfp-anim class to markup
        this.st.image.markup = this.st.image.markup.replace(
          "mfp-figure",
          "mfp-figure mfp-with-anim"
        );
      }
    },
    closeOnContentClick: true,
    midClick: true // allow opening popup on middle mouse click. Always set it to true if you don't provide alternative source.
  });

  // Add anchors for headings
  $('.page__content').find('h1, h2, h3, h4, h5, h6').each(function() {
    var id = $(this).attr('id');
    if (id) {
      var anchor = document.createElement("a");
      anchor.className = 'header-link';
      anchor.href = '#' + id;
      anchor.innerHTML = '<span class=\"sr-only\">Permalink</span><i class=\"fas fa-link\"></i>';
      anchor.title = "Permalink";
      $(this).append(anchor);
    }
  });
});
